export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const t = Math.min(time, 2 * tTop);

  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const F = m * g;

  let motionStateStr = "At the top";
  if (t <= 0.001) {
    motionStateStr = "Ready to toss";
  } else if (v > 0.01) {
    motionStateStr = "Rising";
  } else if (v < -0.01) {
    if (y <= 0.001) {
      motionStateStr = "Back at launch height";
    } else {
      motionStateStr = "Falling";
    }
  }

  const frameObjects = [];

  const leftPanel = sdk.panel({ x: 20, y: 35, w: 290, h: 365, title: "The motion", state: motionStateStr, id: "lane.motion" });
  leftPanel.forEach(obj => frameObjects.push(obj));

  const yMin = 0;
  const yMax = 2.2;
  const axisX = 80;
  const axisY = 360;
  const axisLen = 280;

  const axisObj = sdk.axis("axis.height", {
    x: axisX,
    y: axisY,
    length: axisLen,
    orientation: "y",
    min: yMin,
    max: yMax,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });
  frameObjects.push(axisObj);

  const ballX = axisX;
  const ballY = axisY - (y / yMax) * axisLen;

  const ballObj = sdk.circle("ball.toss", ballX, ballY, 28);
  frameObjects.push(ballObj);

  const vVecs = sdk.vector("vec.v", { x: ballX + 24, y: ballY }, {
    value: v,
    direction: "up",
    scale: 18,
    label: "v"
  });
  vVecs.forEach(obj => frameObjects.push(obj));

  const aVecs = sdk.vector("vec.a", { x: ballX + 54, y: ballY }, {
    value: a,
    direction: "up",
    scale: 18,
    label: "a"
  });
  aVecs.forEach(obj => frameObjects.push(obj));

  const lines = [
    `v = ${v >= 0 ? "+" : ""}${v.toFixed(2)} m/s`,
    `a = ${a.toFixed(1)} m/s²`,
    `Fg = ${F.toFixed(1)} N`
  ];
  const calloutObjs = sdk.callout(ballX + 90, ballY - 24, lines, { id: "callout.toss" });
  calloutObjs.forEach(obj => frameObjects.push(obj));

  const rightPanel = sdk.panel({ x: 330, y: 35, w: 290, h: 365, title: "Velocity graph", state: `a = -${g.toFixed(1)} m/s²`, id: "lane.graph" });
  rightPanel.forEach(obj => frameObjects.push(obj));

  const plotX = 390;
  const plotY = 70;
  const plotW = 210;
  const plotH = 300;
  const tMaxPlot = 1.8;
  const vMinPlot = -5.5;
  const vMaxPlot = 5.5;

  const sampleCount = 24;
  const tracePoints = [];
  for (let i = 0; i <= sampleCount; i++) {
    const st = (t * i) / sampleCount;
    const sv = u - g * st;
    tracePoints.push({ x: st, y: sv });
  }

  const tEnd = 2 * tTop;
  const linePoints = [];
  for (let i = 0; i <= sampleCount; i++) {
    const st = (tEnd * i) / sampleCount;
    const sv = u - g * st;
    linePoints.push({ x: st, y: sv });
  }

  const plotObj = sdk.plot("plot.vt", {
    x: plotX,
    y: plotY,
    w: plotW,
    h: plotH,
    axes: {
      x: { label: "Time", min: 0, max: tMaxPlot, unit: "s" },
      y: { label: "Velocity", min: vMinPlot, max: vMaxPlot, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: linePoints },
      { label: "trace", kind: "line", points: tracePoints }
    ]
  });
  frameObjects.push(plotObj);

  return {
    frame: {
      width: 640,
      height: 420,
      objects: frameObjects,
      readouts: [
        { id: "velocity", value: v },
        { id: "acceleration", value: a },
        { id: "force", value: F },
        { id: "motionState", value: motionStateStr }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: (u * u) / (2 * g),
      height: y,
      velocity: v,
      acceleration: a,
      force: F
    }
  };
}
